/* mage_skin_ai.js — 法师 19 套皮肤基于 32×38 AI 法师帧的程序化染色/取帧层（v54）
 *
 * 加载顺序：必须在 mage_ai.js 之后（index.html 由 Boss 线挂 <script>）。
 *
 * 管线：
 *   1. 底帧 RGBA 像素内嵌在本文件（PQ_PIX，32×38，来源 assets/ai/mage/*.png）。
 *      注意：file:// 启动时 file 图片会污染 canvas，getImageData 抛 SecurityError；
 *      因此染色直接在 TypedArray 像素上做，不再从被污染的 Image/Canvas 读像素。
 *   2. 按 art.js HERO_SKINS 调色板逐像素分区染色（袍身三阶 / 金饰 / 宝珠 / 描边；肤色、灰白、木杖保留），
 *      不触碰旧 16×16 程序化帧。
 *   3. 外部包装全局 getMageSkin / getMageLook / mageSkinFrames：AI 帧就绪且能产出 32×38 帧时接管，
 *      否则一律回退旧实现（保存了旧引用），保证不白屏、不崩。blue 恒走旧路径，视觉与手感不退化。
 *   4. 包装打跳过标记 __pqMageSkinAI；常驻看门狗检测到包装被顶替时自动装回。
 *   5. 永久守卫：每 2s 校验缓存帧集仍是 32×38；被外部 applyPatch 等缩回尺寸时清缓存惰性重建。
 *
 * 入口约定：window.PQ_MAGE_SKIN_AI = { ready:boolean, frames(skinId), framesLook(skinId,eq), guard(), list() }
 * 本文件未加载或未就绪时，mageSkinFrames/getMageSkin 回退原有逻辑。
 *
 * 帧集键（与 ui.js magePoseImg / 死亡帧路径消费口径对齐）：
 *   idle1 idle2 jump fall attack cast dash dashWind squash die + run[]（含 *L / runL 翻转版）
 * 姿态 ← AI 底帧映射（与 mage_ai.js blue 路径同一套动作来源，不改判定/时序）：
 *   idle1/idle2/jump/fall/squash/die ← idle；attack ← cast2；cast ← cast1；
 *   dash ← run0；dashWind ← cast0；run ← run0..3。
 */
(function () {
  'use strict';
  if (window.PQ_MAGE_SKIN_AI && window.PQ_MAGE_SKIN_AI.__stub !== true) return;

  var W = window;
  if (typeof W === 'undefined' || typeof document === 'undefined') return;

  /* ---------- 1. 皮肤调色板（兜底内嵌；运行时优先读全局 HERO_SKINS） ---------- */
  var EMBEDDED = [
    { id: 'blue',     pal: { k: '#1c2450', b: '#38b8f8', B: '#1e78c8', W: '#d8f4ff', o: '#f88838', s: '#f8b040', O: '#c85820', y: '#f8d048' } },
    { id: 'sprout',   pal: { k: '#1c2450', b: '#6bd039', B: '#4e931c', W: '#b8eba8', o: '#f6b828', s: '#f8d754', O: '#b58108', y: '#fbef83' } },
    { id: 'crystal',  pal: { k: '#1c2450', b: '#a06ed8', B: '#5c27b1', W: '#f4edfa', o: '#35c2de', s: '#5dc0e5', O: '#19879c', y: '#88c8ed' } },
    { id: 'azure',    pal: { k: '#1c2450', b: '#47e1c2', B: '#15ae83', W: '#cbf6f2', o: '#e63763', s: '#eb6075', O: '#a81539', y: '#f28d92' } },
    { id: 'steel',    pal: { k: '#1c2450', b: '#8d98b0', B: '#4f6481', W: '#edeff3', o: '#eaaa2a', s: '#eeca53', O: '#a57410', y: '#f4e481' } },
    { id: 'ember',    pal: { k: '#1c2450', b: '#ee362f', B: '#b40811', W: '#f9c2b9', o: '#f6c228', s: '#f8df54', O: '#b58a08', y: '#fbf583' } },
    { id: 'ivory',    pal: { k: '#1c2450', b: '#c6caaf', B: '#9a9d5c', W: '#f5f6f1', o: '#36a4c9', s: '#5aa9d3', O: '#236d85', y: '#81b5df' } },
    { id: 'starcore', pal: { k: '#1c2450', b: '#f8dd62', B: '#e3a702', W: '#fefce9', o: '#ae41d2', s: '#ca66db', O: '#772393', y: '#e18fe6' } },
    { id: 'jade',     pal: { k: '#1c2450', b: '#47c281', B: '#27894c', W: '#afe5cd', o: '#e03e74', s: '#e66583', O: '#a21a48', y: '#ee909d' } },
    { id: 'sunset',   pal: { k: '#1c2450', b: '#f3ac49', B: '#ca6806', W: '#fdf5e4', o: '#248fdb', s: '#4b94e2', O: '#185e91', y: '#76a2ea' } },
    { id: 'nebula',   pal: { k: '#1c2450', b: '#d263e3', B: '#9a1abe', W: '#fbecfc', o: '#efbf2e', s: '#f3db59', O: '#af870d', y: '#f7f287' } },
    { id: 'abyss',    pal: { k: '#1c2450', b: '#27afb9', B: '#157f7d', W: '#74cfe1', o: '#ef552e', s: '#f38759', O: '#af2e0d', y: '#f7b487' } },
    { id: 'coral',    pal: { k: '#1c2450', b: '#ed6e87', B: '#d31249', W: '#fcebec', o: '#36d3c6', s: '#5cd9db', O: '#209086', y: '#85dae5' } },
    { id: 'tide',     pal: { k: '#1c2450', b: '#393ed0', B: '#1c2a93', W: '#ada8eb', o: '#f29f2c', s: '#f4c357', O: '#b16c0b', y: '#f8e086' } },
    { id: 'wraith',   pal: { k: '#1c2450', b: '#69b56e', B: '#3a8439', W: '#cce6d0', o: '#9f49ca', s: '#bc6dd5', O: '#6c298d', y: '#d694e1' } },
    { id: 'magma',    pal: { k: '#1c2450', b: '#f46a2a', B: '#b92e04', W: '#fbd3b7', o: '#fadf2e', s: '#fbf55b', O: '#bea605', y: '#f6fd8c' } },
    { id: 'judge',    pal: { k: '#1c2450', b: '#7c3a68', B: '#542348', W: '#b06e96', o: '#df1631', s: '#eb373d', O: '#930f20', y: '#f16e64' } },
    { id: 'spectra',  pal: { k: '#1c2450', b: '#ce68c4', B: '#7a2870', W: '#f4d0ea', o: '#2e8850', s: '#4cb878', O: '#1c5c34', y: '#8ce8b0' } },
    { id: 'holy',     pal: { k: '#1c2450', b: '#f0eef8', B: '#b0a8c8', W: '#ffffff', o: '#d89020', s: '#f0b840', O: '#a06410', y: '#f8e088' } },
    { id: 'inferno',  pal: { k: '#1c2450', b: '#9e2f5e', B: '#6a1f3c', W: '#d98aa8', o: '#f08a18', s: '#f8b02c', O: '#a85808', y: '#ffd85c' } }
  ];

  function findDef(id) {
    var i, arr;
    try {
      arr = (typeof HERO_SKINS !== 'undefined' && Array.isArray(HERO_SKINS)) ? HERO_SKINS : null;
      if (!arr && W.HERO_SKINS && Array.isArray(W.HERO_SKINS)) arr = W.HERO_SKINS;
    } catch (e) { arr = null; }
    if (arr) {
      for (i = 0; i < arr.length; i++) if (arr[i] && arr[i].id === id) return arr[i];
    }
    for (i = 0; i < EMBEDDED.length; i++) if (EMBEDDED[i].id === id) return EMBEDDED[i];
    return null;
  }

  /* ---------- 2. 内嵌底帧像素（32×38 RGBA，base64 原始字节） ---------- */
  var PQ_PIX = {"idle":"","run0":"","run1":"","run2":"","run3":"","cast0":"","cast1":"","cast2":""};

  function decodePx(b64) {
    if (!b64) return null;
    var bin = atob(b64), n = bin.length, arr = new Uint8ClampedArray(n);
    for (var i = 0; i < n; i++) arr[i] = bin.charCodeAt(i);
    if (n !== 32 * 38 * 4) return null;
    return { w: 32, h: 38, data: arr };
  }

  var SRC = {
    idle: decodePx(PQ_PIX.idle),
    run: [decodePx(PQ_PIX.run0), decodePx(PQ_PIX.run1), decodePx(PQ_PIX.run2), decodePx(PQ_PIX.run3)],
    cast: [decodePx(PQ_PIX.cast0), decodePx(PQ_PIX.cast1), decodePx(PQ_PIX.cast2)]
  };
  var ready = !!(SRC.idle && SRC.idle.data.length === 32 * 38 * 4);

  /* ---------- 3. 逐像素分区染色（TypedArray，不读被污染的 canvas） ---------- */
  function hex(h) {
    h = String(h || '#000000').replace('#', '');
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  function rgbHsl(r, g, b) {
    r /= 255; g /= 255; b /= 255;
    var mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn;
    var h = 0;
    if (d !== 0) {
      if (mx === r) h = ((g - b) / d) % 6;
      else if (mx === g) h = (b - r) / d + 2;
      else h = (r - g) / d + 4;
      h *= 60; if (h < 0) h += 360;
    }
    var l = (mx + mn) / 2, s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
    return { h: h / 360, l: l, s: s };
  }

  /* 调色板映射（沿用 art.js _magePalFromSkin 口径）：
     袍身三阶 b/B/W；金饰 y；宝珠体 o=p.y、珠暗 O=p.s；描边 k。肤色/五官不动。 */
  function magePal(p) {
    return { k: p.k, b: p.b, B: p.B, W: p.W, y: p.y, o: p.y, O: p.s };
  }

  function tintPx(srcPx, pal) {
    var d = new Uint8ClampedArray(srcPx.data);
    var C = { k: hex(pal.k), b: hex(pal.b), B: hex(pal.B), W: hex(pal.W), y: hex(pal.y), o: hex(pal.o), O: hex(pal.O) };
    for (var i = 0; i < d.length; i += 4) {
      var a = d[i + 3];
      if (a < 16) continue;
      var r = d[i], gg = d[i + 1], bb = d[i + 2];
      var hsl = rgbHsl(r, gg, bb), hd = hsl.h * 360, l = hsl.l, s = hsl.s;
      var out;
      if (l <= 0.18) out = C.k;                                  // 描边/暗部轮廓
      else if (s <= 0.13) continue;                              // 纯白/灰木杖保留
      else if ((hd >= 300 || hd <= 45) && l >= 0.34) continue; // 肤色（粉/桃）保留
      else if (hd >= 15 && hd <= 45 && l < 0.45 && s > 0.30) out = C.y; // 腰带/金饰
      else if (hd >= 140 && hd <= 200 && l > 0.72) out = l > 0.85 ? [255, 255, 255] : C.o; // 宝珠
      else out = l < 0.34 ? C.B : (l < 0.62 ? C.b : C.W);       // 袍身三阶
      d[i] = out[0]; d[i + 1] = out[1]; d[i + 2] = out[2];
    }
    var c = document.createElement('canvas');
    c.width = 32; c.height = 38;
    c.getContext('2d').putImageData(new ImageData(d, 32, 38), 0, 0);
    return c;
  }

  function flip(cv) {
    var w = cv.width, h = cv.height;
    var c = document.createElement('canvas');
    c.width = w; c.height = h;
    var g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    g.translate(w, 0); g.scale(-1, 1);
    g.drawImage(cv, 0, 0);
    return c;
  }

  /* ---------- 4. 帧集构建 + 缓存 ---------- */
  var cache = {};

  function buildSet(def) {
    var pal = magePal(def.pal);
    var idle = tintPx(SRC.idle, pal);
    var run = SRC.run.map(function (im) { return tintPx(im || SRC.idle, pal); });
    var cast = SRC.cast.map(function (im, i) { return tintPx(im || SRC.cast[1] || SRC.idle, pal); });

    var set = {
      idle1: idle,
      idle2: run[0],
      jump: idle,
      fall: idle,
      attack: cast[2] || cast[1] || idle,
      cast: cast[1] || idle,
      dash: run[0],
      dashWind: cast[0] || idle,
      squash: idle,
      die: idle,
      run: run
    };
    set.idle1L = flip(set.idle1);
    set.idle2L = flip(set.idle2);
    set.jumpL = flip(set.jump);
    set.fallL = flip(set.fall);
    set.attackL = flip(set.attack);
    set.castL = flip(set.cast);
    set.dashL = flip(set.dash);
    set.dashWindL = flip(set.dashWind);
    set.squashL = flip(set.squash);
    set.dieL = flip(set.die);
    set.runL = set.run.map(flip);
    Object.freeze(set.run);
    Object.freeze(set.runL);
    return set;
  }

  function frames(id) {
    if (!ready) return null;
    var def = findDef(id);
    if (!def || def.id === 'blue') return null;
    if (cache[def.id]) return cache[def.id];
    var set;
    try { set = buildSet(def); } catch (e) {
      try { W.PQ_MAGE_SKIN_AI.lastError = String(e && e.stack || e); } catch (_) {}
      return null;
    }
    cache[def.id] = set;
    return set;
  }

  /* ---------- 5. 装备态叠加（32×38 AI 底帧上叠 SPR.look 部件，不回落 16×16 旧帧） ----------
     部件来源与 ui.js heroLook 同一套：SPR.look.weapon/hat/cape[tier]，tier 0/1/2，16×16。
     合成顺序沿用 heroLook：披风（底层，先画）→ AI 底帧 → 武器（手侧）→ 头饰（头顶）。
     16×16 部件按网格映射到 32×38（sx=32/16=2，sy=38/16），imageSmoothingEnabled=false
     最近邻放大，保持像素硬边，禁止模糊插值。部件缺失/SPR.look 未合入则跳过该槽。 */
  function tier(v) { return (typeof v === 'number' && v >= 0) ? Math.min(v | 0, 2) : -1; }

  function lookPart(slot, t) {
    try {
      if (t < 0 || typeof SPR === 'undefined' || !SPR.look || !SPR.look[slot]) return null;
      return SPR.look[slot][t] || null;
    } catch (e) { return null; }
  }

  function overlayFrame(base, wT, hT, cT) {
    var c = document.createElement('canvas');
    c.width = 32; c.height = 38;
    var g = c.getContext('2d');
    g.imageSmoothingEnabled = false;
    var cape = lookPart('cape', cT), weapon = lookPart('weapon', wT), hat = lookPart('hat', hT);
    if (cape) g.drawImage(cape, 0, 0, 16, 16, 0, 0, 32, 38);   // 披风底层
    g.drawImage(base, 0, 0);                                  // AI 染色底帧
    if (weapon) g.drawImage(weapon, 0, 0, 16, 16, 0, 0, 32, 38); // 武器手侧
    if (hat) g.drawImage(hat, 0, 0, 16, 16, 0, 0, 32, 38);        // 头饰头顶
    return c;
  }

  var eqCache = {};

  function framesEquipped(id, eq) {
    var naked = frames(id);
    if (!naked) return null;
    var wT = tier(eq && eq.w), hT = tier(eq && eq.h), cT = tier(eq && eq.c);
    if (wT < 0 && hT < 0 && cT < 0) return naked;            // 无装备：裸皮肤帧集直通
    var key = id + '|' + wT + ',' + hT + ',' + cT;
    if (eqCache[key]) return eqCache[key];

    var set = {
      idle1: overlayFrame(naked.idle1, wT, hT, cT),
      idle2: overlayFrame(naked.idle2, wT, hT, cT),
      jump: overlayFrame(naked.jump, wT, hT, cT),
      fall: overlayFrame(naked.fall, wT, hT, cT),
      attack: overlayFrame(naked.attack, wT, hT, cT),
      cast: overlayFrame(naked.cast, wT, hT, cT),
      dash: overlayFrame(naked.dash, wT, hT, cT),
      dashWind: overlayFrame(naked.dashWind, wT, hT, cT),
      squash: overlayFrame(naked.squash, wT, hT, cT),
      die: overlayFrame(naked.die, wT, hT, cT),
      run: naked.run.map(function (im) { return overlayFrame(im, wT, hT, cT); })
    };
    set.idle1L = flip(set.idle1);
    set.idle2L = flip(set.idle2);
    set.jumpL = flip(set.jump);
    set.fallL = flip(set.fall);
    set.attackL = flip(set.attack);
    set.castL = flip(set.cast);
    set.dashL = flip(set.dash);
    set.dashWindL = flip(set.dashWind);
    set.squashL = flip(set.squash);
    set.dieL = flip(set.die);
    set.runL = set.run.map(flip);
    Object.freeze(set.run);
    Object.freeze(set.runL);
    eqCache[key] = set;
    return set;
  }

  /* ---------- 6. 包装全局函数（保留旧实现兜底）+ 标记 / 看门狗重装 ---------- */
  var oldGetMageSkin = W.getMageSkin || null;
  var oldGetMageLook = W.getMageLook || null;

  function skinWrapper(id) {
    var f = frames(id);
    if (f) return f;
    return oldGetMageSkin ? oldGetMageSkin(id) : null;
  }
  function lookWrapper(id, eq) {
    // 装备态也接管：在 32×38 AI 底帧上叠 SPR.look 部件；只有本层缺帧/异常时才回落旧实现，
    // 避免法师一穿装备就退回 16×16 旧程序化帧。
    var equippedSet = framesEquipped(id, eq);
    if (equippedSet) return equippedSet;
    if (oldGetMageLook) return oldGetMageLook(id, eq);
    return oldGetMageSkin ? oldGetMageSkin(id) : null;
  }
  function framesWrapper(id) {
    var f = frames(id);
    if (f) return f;
    return oldGetMageSkin ? oldGetMageSkin(id || 'blue') : null;
  }
  var WRAP = [skinWrapper, lookWrapper, framesWrapper];

  function installWrappers() {
    for (var i = 0; i < WRAP.length; i++) WRAP[i].__pqMageSkinAI = true;
    W.getMageSkin = skinWrapper;
    W.getMageLook = lookWrapper;
    W.mageSkinFrames = framesWrapper;
  }
  function watchdog() {
    // 检测包装是否被外部脚本顶替；被顶替就自动装回（旧实现引用仍保留作兜底）。
    if (W.getMageSkin !== skinWrapper) W.getMageSkin = skinWrapper;
    if (W.getMageLook !== lookWrapper) W.getMageLook = lookWrapper;
    if (W.mageSkinFrames !== framesWrapper) W.mageSkinFrames = framesWrapper;
  }

  /* ---------- 7. 永久守卫：缓存帧集尺寸校验，异常即清缓存惰性重建 ---------- */
  var SINGLE = ['idle1', 'idle2', 'jump', 'fall', 'attack', 'cast', 'dash', 'dashWind', 'squash', 'die'];
  function frameOk(f) { return f && typeof f.width === 'number' && f.width === 32 && typeof f.height === 'number' && f.height === 38; }
  function setOk(s) {
    var i;
    for (i = 0; i < SINGLE.length; i++) if (!frameOk(s[SINGLE[i]])) return false;
    if (!Array.isArray(s.run) || !s.run.length) return false;
    for (i = 0; i < s.run.length; i++) if (!frameOk(s.run[i])) return false;
    return true;
  }
  function guard() {
    if (!ready) return;
    var key;
    for (key in cache) {
      if (!Object.prototype.hasOwnProperty.call(cache, key)) continue;
      if (!setOk(cache[key])) delete cache[key];
    }
    for (key in eqCache) {
      if (!Object.prototype.hasOwnProperty.call(eqCache, key)) continue;
      if (!setOk(eqCache[key])) delete eqCache[key];
    }
    watchdog();
  }

  installWrappers();

  W.PQ_MAGE_SKIN_AI = {
    __stub: false,
    ready: ready,
    frames: frames,
    framesLook: framesEquipped,
    guard: guard,
    list: function () { return EMBEDDED.map(function (x) { return x.id; }); }
  };

  setInterval(guard, 2000);
})();
